import React from 'react';
import { Clock, CheckCircle, XCircle, Building2, Calendar } from 'lucide-react';

const MyApplicationsPage = () => {
  // بيانات تجريبية (سيتم ربطها لاحقاً بقاعدة البيانات)
  const myApplications = [
    {
      id: 1,
      company: "Tech Solutions",
      position: "Frontend Developer",
      date: "2026-03-20",
      status: "Pending",
    },
    {
      id: 2,
      company: "Innovation Hub",
      position: "Mobile App Intern",
      date: "2026-03-15",
      status: "Accepted",
    },
    {
      id: 3,
      company: "Data Group",
      position: "Data Analyst",
      date: "2026-03-10",
      status: "Refused",
    }
  ];

  const getStatusStyle = (status) => {
    switch (status) {
      case 'Accepted': return { color: '#10b981', bg: '#ecfdf5', icon: <CheckCircle size={16} /> };
      case 'Refused': return { color: '#ef4444', bg: '#fef2f2', icon: <XCircle size={16} /> };
      default: return { color: '#f59e0b', bg: '#fffbeb', icon: <Clock size={16} /> };
    }
  };

  return (
    <div style={{ padding: '40px 20px', maxWidth: '1000px', margin: '0 auto', minHeight: '80vh' }}>
      <div style={{ marginBottom: '30px', textAlign: 'left' }}>
        <h1 style={{ color: '#4a3f6b', fontSize: '28px' }}>My Applications</h1>
        <p style={{ color: '#666' }}>Track the status of your internship applications in real-time.</p>
      </div>

      <div style={{ backgroundColor: 'white', borderRadius: '15px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#f8f9fa', borderBottom: '2px solid #eee' }}>
            <tr>
              <th style={{ padding: '18px', color: '#444' }}>Company & Role</th>
              <th style={{ padding: '18px', color: '#444' }}>Date Applied</th>
              <th style={{ padding: '18px', color: '#444' }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {myApplications.map((app) => {
              const style = getStatusStyle(app.status);
              return (
                <tr key={app.id} style={{ borderBottom: '1px solid #f0f0f0', transition: '0.3s' }}>
                  <td style={{ padding: '18px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <div style={{ backgroundColor: '#f3e8ff', padding: '10px', borderRadius: '10px' }}>
                        <Building2 color="#7e22ce" size={20} />
                      </div>
                      <div>
                        <div style={{ fontWeight: 'bold', color: '#333' }}>{app.position}</div>
                        <div style={{ fontSize: '13px', color: '#777' }}>{app.company}</div>
                      </div>
                    </div>
                  </td>
                  <td style={{ padding: '18px', color: '#666', fontSize: '14px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                      <Calendar size={14} /> {app.date}
                    </div>
                  </td>
                  <td style={{ padding: '18px' }}>
                    <span style={{ 
                      display: 'inline-flex', alignItems: 'center', gap: '6px',
                      padding: '6px 14px', borderRadius: '20px', fontSize: '13px', fontWeight: '600',
                      color: style.color, backgroundColor: style.bg 
                    }}>
                      {style.icon} {app.status}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default MyApplicationsPage;
